import type { ModularAppDefinition } from '../../device/modularApp/types';

// Base64 of the Tron modular app artifacts, hardcoded for now. Built from trezor-firmware
// bieleluk/sdk-wip (CI run 35578205255, extapp-emu-tron-t3w1-en): app id "tron.trezor.com" v0.1.0,
// ring 0. Emulator build; swap for the device `.tapp` when loading onto T3W1 hardware.
// The device does not require a proof for this ring-0 build, so the proof is empty.
const TRON_APP_BINARY_BASE64 =
    '';
const TRON_APP_PROOF_BASE64 = '';
const TRON_APP_ROOT_PACKET_BASE64 =
    '';

// Maps @trezor/protobuf Tron wire message names to the Tron app-local MessageType ids
// (sdk/apps/tron/protob/messages.proto).
const TRON_MESSAGE_IDS: ModularAppDefinition['messageIds'] = {
    TronGetAddress: 0,
    TronAddress: 1,
    TronSignTx: 2,
    TronSignature: 3,
    TronContractRequest: 4,
    TronTransferContract: 5,
    TronTriggerSmartContract: 6,
    TronFreezeBalanceV2Contract: 7,
    TronUnfreezeBalanceV2Contract: 8,
    TronWithdrawUnfreeze: 9,
    TronVoteWitnessContract: 10,
    TronWithdrawBalance: 11,
};

export const TRON_MODULAR_APP: ModularAppDefinition = {
    id: 'tron.trezor.com',
    binary: Buffer.from(TRON_APP_BINARY_BASE64, 'base64'),
    proof: Buffer.from(TRON_APP_PROOF_BASE64, 'base64'),
    rootPacket: Buffer.from(TRON_APP_ROOT_PACKET_BASE64, 'base64'),
    messageIds: TRON_MESSAGE_IDS,
};
